// Rag.js
import React, { useState, useEffect, useRef, useCallback } from 'react';
import styles from './chat.module.css';
import { callApi } from '../api/client';
import { useLocation } from 'react-router-dom';

export default function Rag() {
  const { search } = useLocation();
  const [queryInput, setQueryInput] = useState('');
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const containerRef = useRef(null);
  const initial = useRef(false);

  const appendMessage = useCallback((sender, text) => {
    setMessages(prev => [...prev, { sender, text }]);
  }, []);

  const fetchAnswer = useCallback(async (prompt) => {
    setLoading(true);
    setError('');
    try {
      const { answer } = await callApi('rag', 'POST', { query: prompt });
      appendMessage('bot', answer);
    } catch (err) {
      console.error(err);
      setError('Error fetching response.');
    } finally {
      setLoading(false);
    }
  }, [appendMessage]);

  // One-time initial prompt from URL
  useEffect(() => {
    if (initial.current) return;
    initial.current = true;

    const params = new URLSearchParams(search);
    const q = params.get('query')?.trim();
    if (q) {
      appendMessage('user', q);
      fetchAnswer(q);
    }
    // only run once
  }, []);

  // Auto-scroll on new messages
  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages]);

  const submitQuery = (e) => {
    e.preventDefault();
    const trimmed = queryInput.trim();
    if (!trimmed || loading) return;
    appendMessage('user', trimmed);
    setQueryInput('');
    fetchAnswer(trimmed);
  };

  return (
    <div className={styles.chatContainer}>
      <div className={styles.messageList} ref={containerRef}>
        {messages.map((m, i) => (
          <div
            key={i}
            className={m.sender === 'user' ? styles.userMsg : styles.botMsg}
          >
            {m.text}
          </div>
        ))}
        {loading && <div className={styles.loading}>Loading...</div>}
        {error && <div className={styles.error}>{error}</div>}
      </div>

      <form onSubmit={submitQuery} className={styles.inputBar}>
        <input
          type="text"
          className={styles.input}
          placeholder="Ask your question..."
          value={queryInput}
          onChange={(e) => setQueryInput(e.target.value)}
          disabled={loading}
        />
        <button
          type="submit"
          className={styles.sendBtn}
          disabled={!queryInput.trim() || loading}
        >
          Send
        </button>
      </form>
    </div>
  );
}
